def isbn_valid(s: str) -> bool:
    t = s.replace('-', '').replace(' ', '')
    if len(t) == 10:
        total = 0
        for i, ch in enumerate(t):
            if i < 9:
                if not ch.isdigit():
                    return False
                total += (i + 1) * int(ch)
            else:
                if ch == 'X':
                    val = 10
                elif ch.isdigit():
                    val = int(ch)
                else:
                    return False
                total += 10 * val
        return total % 11 == 0
    elif len(t) == 13:
        if not t.isdigit():
            return False
        total = 0
        for i, ch in enumerate(t):
            weight = 1 if i % 2 == 0 else 3
            total += weight * int(ch)
        return total % 10 == 0
    else:
        return False
